={{ JSON.stringify({
  document_id: $('Normalize Input Data').item.json.document_id,
  report_name: 'Orchestrator — ' + $('Normalize Input Data').item.json.document_name,
  classification: $('Normalize Input Data').item.json.visibility || 'Internal',
  sections: {
    attack_types: $json.parsed_report?.attack_types ?? $json.parsed_report?.attacks ?? [],
    general_risk_assessment: $json.parsed_report?.general_risk_assessment ?? [],
    vulnerabilities: $json.parsed_report?.vulnerabilities ?? $json.parsed_report?.vulnerability ?? [],
    anomalies: $json.parsed_report?.anomalies ?? $json.parsed_report?.detected_anomalies ?? [],
    timeline: $json.parsed_report?.timeline ?? []
  },
  threat_intel: ($('Risk Scoring Engine').item.json.classified_iocs ?? []).map(ioc => {
    const looked_up = ioc.value === $('Risk Scoring Engine').item.json.data?.ipAddress;
    return {
      indicator: ioc.value,
      indicator_type: ioc.type === 'IP Address' ? 'ip'
        : ioc.type === 'File Hash' ? 'hash' : 'domain',
      category: ioc.category,
      source: looked_up ? 'abuseipdb' : 'n8n',
      reputation_score: looked_up
        ? $('Risk Scoring Engine').item.json.ip_reputation_score : null,
      risk_level: looked_up
        ? $('Risk Scoring Engine').item.json.ti_risk_level : null,
      country: looked_up ? $('Risk Scoring Engine').item.json.ip_country : null,
      usage_type: looked_up ? $('Risk Scoring Engine').item.json.ip_usage_type : null
    };
  })
}) }}

